using System;
using System.Linq;
using System.IO;
using System.Collections.Generic;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using System.Windows.Input;
using System.Runtime.InteropServices;
using NAudio.CoreAudioApi;
using Forms=System.Windows.Forms;
namespace Island11;
public partial class MainWindow {
 sealed class Extras { public bool ClipboardEnabled{get;set;} public bool Top{get;set;} public bool Graphite{get;set;} public double Scale{get;set;}=1; public int Delay{get;set;}=550; public List<ClipEntry> Clips{get;set;}=new(); public List<Link> Links{get;set;}=new(); }
 sealed class ClipEntry { public string Text{get;set;}=""; public bool Pinned{get;set;} }
 sealed class Link { public string Name{get;set;}=""; public string Target{get;set;}=""; }
 Extras extras=new(); bool extrasReady;
 string extrasPath=>Path.Combine(Log.Folder,"extras.json");
 void LoadExtras(){try{if(File.Exists(extrasPath))extras=JsonSerializer.Deserialize<Extras>(File.ReadAllText(extrasPath))??new();}catch(Exception e){Log.Write(e);} extras.Scale=Math.Clamp(extras.Scale,.85,1.2); extras.Delay=Math.Clamp(extras.Delay,200,2000); clipboardOn=extras.ClipboardEnabled;collapse.Interval=TimeSpan.FromMilliseconds(extras.Delay);Shell.Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(extras.Graphite?"#191B20":"#050607"));extrasReady=true;}
 void SaveExtras(){try{Directory.CreateDirectory(Log.Folder);File.WriteAllText(extrasPath,JsonSerializer.Serialize(extras));}catch(Exception e){Report("Не удалось сохранить настройки",e);}}
 void ShowSection(object sender,RoutedEventArgs e){section=(string)((Button)sender).Tag;Expanded.Visibility=section=="music"?Visibility.Visible:Visibility.Collapsed;ExtraPage.Visibility=section=="music"?Visibility.Collapsed:Visibility.Visible;if(section!="music")BuildPage();}
 void ReadClipboard(){if(!extrasReady||!clipboardOn)return;try{if(!Clipboard.ContainsText())return;string t=Clipboard.GetText();if(string.IsNullOrWhiteSpace(t)||t.Length>20000||t==lastClip)return;lastClip=t;var prev=extras.Clips.FirstOrDefault(x=>x.Text==t);if(prev!=null)extras.Clips.Remove(prev);extras.Clips.Insert(0,prev??new ClipEntry{Text=t});while(extras.Clips.Count(x=>!x.Pinned)>40){var old=extras.Clips.Last(x=>!x.Pinned);extras.Clips.Remove(old);}SaveExtras();if(section=="clipboard"&&expanded)BuildPage();}catch(System.Runtime.InteropServices.ExternalException){}catch(Exception e){Log.Write(e);}}
 Button Btn(string text,Action action){var b=new Button{Content=text,Margin=new Thickness(0,3,5,3),Padding=new Thickness(10,6,10,6),HorizontalAlignment=HorizontalAlignment.Left};b.Click+=(_,_)=>action();return b;}
 TextBlock Txt(string t)=>new(){Text=t,TextWrapping=TextWrapping.Wrap,Foreground=(Brush)FindResource("Muted"),Margin=new Thickness(0,3,0,9)};
 void BuildPage(){ExtraItems.Children.Clear();
  if(section=="clipboard") {ExtraTitle.Text="Буфер обмена";var check=new CheckBox{Content="Сохранять историю текста и ссылок",IsChecked=clipboardOn,Foreground=Brushes.White,Margin=new Thickness(0,5,0,8)};check.Click+=(_,_)=>{clipboardOn=check.IsChecked==true;extras.ClipboardEnabled=clipboardOn;lastClip="";SaveExtras();};ExtraItems.Children.Add(check);ExtraItems.Children.Add(Txt("История хранится на этом ПК в открытом виде и может содержать пароли. Отключайте её при работе с секретами."));ExtraItems.Children.Add(Btn("Очистить историю",()=>{extras.Clips.Clear();SaveExtras();BuildPage();}));
   foreach(var clip in extras.Clips.ToArray()){var card=new Border{Background=new SolidColorBrush(Color.FromRgb(26,29,34)),CornerRadius=new CornerRadius(12),Padding=new Thickness(10),Margin=new Thickness(0,3,0,3)};var panel=new StackPanel();panel.Children.Add(new TextBlock{Text=clip.Text,TextWrapping=TextWrapping.Wrap,MaxHeight=65,TextTrimming=TextTrimming.CharacterEllipsis,ToolTip=clip.Text});var buttons=new StackPanel{Orientation=Orientation.Horizontal};buttons.Children.Add(Btn("Копировать",()=>{try{Clipboard.SetText(clip.Text);lastClip=clip.Text;Status.Text="Скопировано";}catch(Exception ex){Report("Буфер занят",ex);}}));buttons.Children.Add(Btn(clip.Pinned?"Открепить":"Закрепить",()=>{clip.Pinned=!clip.Pinned;SaveExtras();BuildPage();}));buttons.Children.Add(Btn("Удалить",()=>{extras.Clips.Remove(clip);SaveExtras();BuildPage();}));panel.Children.Add(buttons);card.Child=panel;ExtraItems.Children.Add(card);}return;}
  if(section=="sound"){ExtraTitle.Text="Звук";try{using var en=new MMDeviceEnumerator();using var current=en.GetDefaultAudioEndpoint(DataFlow.Render,Role.Multimedia);string id=current.ID;ExtraItems.Children.Add(Btn(current.AudioEndpointVolume.Mute?"Включить звук":"Выключить звук",()=>{try{using var e=new MMDeviceEnumerator();using var d=e.GetDefaultAudioEndpoint(DataFlow.Render,Role.Multimedia);d.AudioEndpointVolume.Mute=!d.AudioEndpointVolume.Mute;BuildPage();}catch(Exception x){Report("Не удалось изменить звук",x);}}));ExtraItems.Children.Add(Txt("Вывод звука"));foreach(var item in en.EnumerateAudioEndPoints(DataFlow.Render,DeviceState.Active)){using(item){string target=item.ID;string title=(target==id?"✓  ":"")+item.FriendlyName;ExtraItems.Children.Add(Btn(title,()=>{try{AudioRouting.Select(target);BuildPage();}catch(Exception x){Report("Не удалось выбрать устройство вывода",x);}}));}}}catch(Exception ex){Log.Write(ex);ExtraItems.Children.Add(Txt("Аудиоустройства недоступны"));}ExtraItems.Children.Add(Btn("Параметры звука Windows",()=>Launch("ms-settings:sound")));return;}
  if(section=="calendar"){BuildDarkCalendar();return;}
  if(section=="launch"){ExtraTitle.Text="Быстрый запуск";ExtraItems.Children.Add(Txt("Добавь программу, папку или веб-адрес."));var name=new TextBox{Margin=new Thickness(0,3,0,5),ToolTip="Название"};var path=new TextBox{Margin=new Thickness(0,3,0,5),ToolTip="Путь к файлу, папке или URL"};ExtraItems.Children.Add(new TextBlock{Text="Название"});ExtraItems.Children.Add(name);ExtraItems.Children.Add(new TextBlock{Text="Путь или адрес"});ExtraItems.Children.Add(path);ExtraItems.Children.Add(Btn("Добавить",()=>{if(string.IsNullOrWhiteSpace(name.Text)||string.IsNullOrWhiteSpace(path.Text))return;extras.Links.Add(new Link{Name=name.Text.Trim(),Target=path.Text.Trim()});SaveExtras();BuildPage();}));foreach(var link in extras.Links.ToArray()){var row=new StackPanel{Orientation=Orientation.Horizontal};row.Children.Add(Btn(link.Name,()=>Launch(link.Target)));row.Children.Add(Btn("×",()=>{extras.Links.Remove(link);SaveExtras();BuildPage();}));ExtraItems.Children.Add(row);}return;}
  if(section=="settings"){ExtraTitle.Text="Настройки";ExtraItems.Children.Add(Txt("Положение, размер и поведение панели"));ExtraItems.Children.Add(Btn(extras.Top?"Расположение: сверху":"Расположение: снизу",()=>{extras.Top=!extras.Top;var screen=Forms.Screen.FromPoint(new System.Drawing.Point((int)settings.CenterX,(int)settings.BottomY));settings.BottomY=extras.Top?screen.Bounds.Top+38:screen.Bounds.Bottom-6;SaveExtras();settings.Save();Position();BuildPage();}));ExtraItems.Children.Add(Btn(extras.Graphite?"Тема: графит":"Тема: чёрная",()=>{extras.Graphite=!extras.Graphite;Shell.Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(extras.Graphite?"#191B20":"#050607"));SaveExtras();BuildPage();}));ExtraItems.Children.Add(new TextBlock{Text="Размер панели"});var size=new Slider{Minimum=.85,Maximum=1.2,Value=extras.Scale,Margin=new Thickness(0,5,0,8)};size.ValueChanged+=(_,_)=>{extras.Scale=size.Value;SaveExtras();};ExtraItems.Children.Add(size);ExtraItems.Children.Add(new TextBlock{Text="Задержка сворачивания (сек.)"});var delay=new Slider{Minimum=.2,Maximum=2,Value=extras.Delay/1000.0,Margin=new Thickness(0,5,0,8)};delay.ValueChanged+=(_,_)=>{extras.Delay=(int)(delay.Value*1000);collapse.Interval=TimeSpan.FromMilliseconds(extras.Delay);SaveExtras();};ExtraItems.Children.Add(delay);ExtraItems.Children.Add(Btn("Выбор звукового устройства",()=>Launch("ms-settings:sound")));return;}
 }
 async void SeekTrack(object sender,MouseButtonEventArgs e){var s=media.Current;if(s==null||!timeline.Available)return;try{var t=s.GetTimelineProperties();double ratio=Math.Clamp(e.GetPosition(InsideProgress).X/Math.Max(InsideProgress.ActualWidth,1),0,1);long ticks=t.StartTime.Ticks+(long)((t.EndTime-t.StartTime).Ticks*ratio);if(!await s.TryChangePlaybackPositionAsync(ticks))Status.Text="Источник не поддерживает перемотку";else await RefreshMedia();}catch(Exception ex){Report("Не удалось перемотать трек",ex);}}
}
